    "description": "CÔNG TY CỔ PHẦN OMINEXT tuyển dụng System & Security Engineer.\n\n* Giám sát an ninh mạng\n* Giám sát, phân tích và phản hồi các sự kiện an ninh mạng thông qua hệ thống SIEM.\n* Vận hành Security Operations Center (SOC), theo dõi log từ Firewall, IDS/IPS, EDR.\n* Phát hiện, phân tích và xử lý các cuộc tấn công mạng, malware, phishing.\n\n* Quản trị bảo mật hệ thống\n* Quản trị Firewall (Fortinet, Palo Alto, Checkpoint), WAF, hệ thống DLP.\n* Triển khai và quản lý giải pháp endpoint protection, antivirus doanh nghiệp.\n* Thiết lập chính sách bảo mật, kiểm soát truy cập, mã hóa dữ liệu.\n\n* Đánh giá & kiểm tra\n* Thực hiện đánh giá rủi ro bảo mật định kỳ, vulnerability scanning.\n* Kiểm tra penetration test nội bộ và phối hợp với bên thứ ba.\n* Xây dựng chính sách và quy trình an ninh mạng theo tiêu chuẩn ISO 27001.\n\n* Đào tạo & nâng cao nhận thức\n* Đào tạo nhân viên về an toàn thông tin, phòng chống lừa đảo trực tuyến.\n* Cập nhật xu hướng tấn công mạng mới, nghiên cứu giải pháp phòng chống.",
