    "description": "Confidential tuyển dụng Nhân Viên IT.\n\n* Quản lý hệ thống CNTT\n* Quản trị, vận hành toàn bộ hệ thống máy tính, mạng LAN/WAN, Internet, WiFi, điện thoại IP, camera an ninh.\n* Đảm bảo hệ thống CNTT hoạt động liên tục, ổn định, an toàn.\n* Quản lý phần mềm, phần cứng và trang thiết bị CNTT.\n\n* Hỗ trợ nghiệp vụ IT\n* Hỗ trợ các phòng ban sử dụng và xử lý sự cố phần mềm, phần cứng.\n* Cài đặt, cấu hình máy tính, máy in, thiết bị ngoại vi cho nhân viên mới.\n* Quản lý tài khoản người dùng, email, phân quyền truy cập.\n\n* Quản lý server & an ninh mạng\n* Theo dõi, kiểm tra, duy trì hoạt động Server, Firewall, backup dữ liệu định kỳ.\n* Đảm bảo an toàn thông tin, phòng chống virus, hacker, rò rỉ dữ liệu.\n\n* Bảo trì & phát triển\n* Bảo trì định kỳ thiết bị IT, đề xuất nâng cấp và thay thế.\n* Nghiên cứu, đề xuất giải pháp công nghệ mới phù hợp nhu cầu doanh nghiệp.\n* Thực hiện các công việc khác theo phân công của quản lý.",
