    "description": "Ahamove tuyển dụng Nhân Viên IT Phần Cứng & Mạng Văn Phòng.\n\n* Thiết kế & triển khai hạ tầng mạng\n* Thiết kế, triển khai hệ thống mạng LAN/WAN/WiFi cho văn phòng và chi nhánh.\n* Cấu hình Router, Switch (Cisco, Juniper, Aruba), đảm bảo kết nối ổn định.\n* Triển khai hệ thống VPN Site-to-Site, Remote Access VPN cho nhân viên.\n\n* Quản trị & giám sát\n* Giám sát lưu lượng mạng, phát hiện và xử lý kịp thời các sự cố, tắc nghẽn.\n* Quản trị thiết bị Firewall (Fortinet, Palo Alto, pfSense), thiết lập chính sách bảo mật.\n* Vận hành hệ thống DNS, DHCP, Proxy, Load Balancer.\n\n* Bảo mật mạng\n* Thiết lập và quản lý chính sách ACL, VLAN, QoS, NAT, PAT.\n* Giám sát an ninh mạng, phát hiện và ngăn chặn xâm nhập (IDS/IPS).\n* Đánh giá rủi ro bảo mật, kiểm tra penetration test định kỳ.\n\n* Tài liệu & báo cáo\n* Xây dựng tài liệu hạ tầng mạng, sơ đồ topology.\n* Lập báo cáo hiệu suất mạng định kỳ, đề xuất phương án tối ưu.",
