    "description": "Tập Đoàn Tân Hiệp Phát đang tuyển dụng IT Helpdesk Technician (Desktop Support). Chịu trách nhiệm vận hành, xử lý sự cố mạng, máy tính, hệ điều hành Windows/Linux, khắc phục sự cố phần cứng/phần mềm.\n\n* Quản lý hệ thống CNTT\n* Cài đặt, quản lý, vận hành toàn bộ hệ thống máy tính, mạng LAN/WAN, internet, wifi, điện thoại IP, camera an ninh.\n* Đảm bảo hệ thống CNTT hoạt động liên tục, ổn định, an toàn.\n* Quản lý phần mềm nhân sự.\n\n* Hỗ trợ người dùng nghiệp vụ IT\n* Hỗ trợ các phòng ban sử dụng và hỗ trợ các phần mềm khách hàng, PMS (Property Management System), POS (Point of Sale), Antivirus, HRM, CRM.\n* Hỗ trợ người dùng sử dụng phần mềm.\n\n* Quản lý server & an ninh mạng\n* Theo dõi, kiểm tra, duy trì hoạt động Server, cache server, firewall, backup định kỳ.\n* Đảm bảo an toàn thông tin, phòng chống virus, hacker, rò rỉ dữ liệu.\n\n* Bảo trì & xử lý sự cố\n* Quản trị & bảo trì toàn bộ hệ thống IT, thiết bị văn phòng (máy in, máy chiếu, camera...).\n* Xử lý sự cố kỹ thuật của hệ thống, đảm bảo hệ thống liên tục vận hành tốt, đúng theo yêu cầu của khách sạn.\n\n* Làm việc với nhà cung cấp\n* Liên hệ, phối hợp và giám sát các nhà thầu/đối tác liên quan đến hệ thống CNTT, phần mềm, phần cứng, bảo trì thiết bị.\n* Thực hiện các công việc khác theo phân công của Trưởng bộ phận.",
