    "description": "Mobifone Global tuyển dụng Nhân Viên IT Helpdesk (Hỗ Trợ Khách Hàng Doanh Nghiệp).\n\n* Tiếp nhận và xử lý các yêu cầu hỗ trợ kỹ thuật từ người dùng qua hệ thống ticket, email, điện thoại.\n* Cài đặt, cấu hình và bảo trì máy tính, laptop, máy in, thiết bị ngoại vi cho nhân viên.\n* Xử lý sự cố phần mềm: hệ điều hành Windows/macOS, bộ ứng dụng Microsoft 365, phần mềm nội bộ.\n* Quản lý tài khoản Active Directory, email doanh nghiệp, phân quyền truy cập tài nguyên mạng.\n* Hỗ trợ kết nối VPN, cấu hình remote desktop cho nhân viên làm việc từ xa.\n* Theo dõi hiệu suất hệ thống, cập nhật bản vá bảo mật, diệt virus định kỳ.\n* Ghi chép lại quy trình xử lý sự cố, xây dựng bộ tài liệu hướng dẫn sử dụng nội bộ.\n* Phối hợp với các bộ phận khác để triển khai các dự án CNTT mới.",
